self.KB_CONTENT["card:779413"]={"id":"card:779413","ty":"card","sourceId":"779413","title":"『暫出/入歸還建立作業(IDL)』的作業目的為何？","ver":"GP4以上","topic":"暫出入","keywords":["暫出入","庫存","狀況","料件"],"y":"explain","answer":"可以輸入、查詢、修改、刪除庫存中所借出或借入之料件歸還狀況。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
